def moveZeroes(nums):

    if len(nums) == 1:
        return nums

    size = len(nums)
    write_index = 0
    for i in range(0, size):
        if nums[i] != 0:
            nums[write_index] = nums[i]
            write_index += 1
    for i in range(write_index, size):
        nums[i] = 0

    return nums

