import numpy as np

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    divisors = np.arange(3, int(np.sqrt(n)) + 1, 2)
    return not np.any(n % divisors == 0)

