def fourSumCount(nums1, nums2, nums3, nums4):

    from collections import defaultdict
    hashmap = defaultdict(int)

    for a in nums1:
        for b in nums2:
            hashmap[a + b] += 1

    ans = 0
    for c in nums3:
        for d in nums4:
            if -(c + d) in hashmap:
                ans += hashmap[-(c+d)]

    return ans 

